RAG_SERVER = "from http.server import BaseHTTPRequestHandler, HTTPServer\nimport json\n\n\nclass Handler(BaseHTTPRequestHandler):\n    def _reply(self, payload, status=200):\n        self.send_response(status)\n        self.send_header('Content-Type', 'application/json')\n        self.end_headers()\n        self.wfile.write(json.dumps(payload).encode('utf-8'))\n\n    def do_GET(self):\n        if self.path == '/health':\n            self._reply({'ok': True, 'service': 'rag'})\n            return\n        self._reply({'error': 'not found'}, status=404)\n\n\nif __name__ == '__main__':\n    server = HTTPServer(('0.0.0.0', 8090), Handler)\n    print('RAG service listening on :8090')\n    server.serve_forever()\n"

SPEC_ROUTER_SERVER = 'from __future__ import annotations\n\nimport json\nimport os\nimport re\nimport time\nimport urllib.error\nimport urllib.request\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\n\n\ndef tokenize_text(text: str) -> list[str]:\n    return [tok for tok in re.split(r"\\s+", (text or "").strip()) if tok]\n\n\ndef http_json(method: str, url: str, payload: dict | None = None, timeout: float = 20.0) -> dict:\n    data = json.dumps(payload or {}).encode("utf-8") if payload is not None else None\n    req = urllib.request.Request(\n        url,\n        data=data,\n        headers={"Content-Type": "application/json"},\n        method=method,\n    )\n    with urllib.request.urlopen(req, timeout=timeout) as resp:\n        body = resp.read().decode("utf-8")\n    return json.loads(body) if body else {}\n\n\ndef extract_completion_text(resp: dict) -> str:\n    if not isinstance(resp, dict):\n        return ""\n    choices = resp.get("choices", []) if isinstance(resp.get("choices", []), list) else []\n    if not choices:\n        return ""\n    c0 = choices[0] if isinstance(choices[0], dict) else {}\n    text = c0.get("text")\n    if isinstance(text, str) and text.strip():\n        return text\n    msg = c0.get("message") if isinstance(c0.get("message"), dict) else {}\n    content = msg.get("content")\n    if isinstance(content, str):\n        return content\n    return ""\n\n\ndef request_model_tokens(\n    *,\n    api_url: str,\n    model: str,\n    prompt: str,\n    max_tokens: int,\n    timeout: float,\n) -> tuple[list[str], float]:\n    started = time.perf_counter()\n    resp = http_json(\n        "POST",\n        api_url.rstrip("/"),\n        payload={\n            "model": model,\n            "prompt": prompt,\n            "max_tokens": max(1, int(max_tokens)),\n            "temperature": 0,\n        },\n        timeout=timeout,\n    )\n    text = extract_completion_text(resp)\n    took_ms = (time.perf_counter() - started) * 1000.0\n    return tokenize_text(text), took_ms\n\n\ndef _first_token(tokens: list[str]) -> str:\n    if not tokens:\n        return ""\n    return str(tokens[0])\n\n\ndef run_streaming_acceptance_loop(\n    *,\n    prompt: str,\n    draft_model: str,\n    target_model: str,\n    draft_url: str,\n    target_url: str,\n    max_tokens: int,\n    timeout: float,\n) -> dict:\n    accepted = 0\n    compared = 0\n    rejected = 0\n    output_tokens: list[str] = []\n    draft_errors: list[str] = []\n    step_trace: list[dict] = []\n    draft_ms_total = 0.0\n    target_ms_total = 0.0\n\n    for step in range(max(1, int(max_tokens))):\n        running_prompt = (prompt + " " + " ".join(output_tokens)).strip()\n\n        draft_token = ""\n        draft_step_ms = 0.0\n        try:\n            draft_tokens, draft_step_ms = request_model_tokens(\n                api_url=draft_url,\n                model=draft_model,\n                prompt=running_prompt,\n                max_tokens=1,\n                timeout=timeout,\n            )\n            draft_token = _first_token(draft_tokens)\n        except Exception as e:\n            draft_errors.append(str(e))\n\n        target_tokens, target_step_ms = request_model_tokens(\n            api_url=target_url,\n            model=target_model,\n            prompt=running_prompt,\n            max_tokens=1,\n            timeout=timeout,\n        )\n        target_token = _first_token(target_tokens)\n\n        draft_ms_total += draft_step_ms\n        target_ms_total += target_step_ms\n\n        if not target_token:\n            break\n\n        compared += 1\n        matched = bool(draft_token) and draft_token == target_token\n        if matched:\n            accepted += 1\n        else:\n            rejected += 1\n\n        output_tokens.append(target_token)\n        step_trace.append(\n            {\n                "step": step + 1,\n                "draft": draft_token,\n                "target": target_token,\n                "accepted": matched,\n            }\n        )\n\n    acceptance_rate = (accepted / compared) if compared else 0.0\n    out = {\n        "accepted_tokens": accepted,\n        "compared_tokens": compared,\n        "rejected_tokens": rejected,\n        "acceptance_rate": round(acceptance_rate, 4),\n        "output_tokens": output_tokens,\n        "draft_token_count": compared,\n        "target_token_count": compared,\n        "draft_call_ms": round(draft_ms_total, 2),\n        "target_call_ms": round(target_ms_total, 2),\n        "loop_mode": "stream_acceptance",\n        "steps": step_trace,\n    }\n    if draft_errors:\n        out["draft_error"] = "; ".join(draft_errors)[:1000]\n    return out\n\n\ndef run_speculative_loop(draft_tokens: list[str], target_tokens: list[str]) -> dict:\n    accepted = 0\n    compared = min(len(draft_tokens), len(target_tokens))\n    out_tokens: list[str] = []\n\n    for i in range(compared):\n        d = draft_tokens[i]\n        t = target_tokens[i]\n        if d == t:\n            accepted += 1\n            out_tokens.append(d)\n        else:\n            out_tokens.append(t)\n\n    if len(target_tokens) > compared:\n        out_tokens.extend(target_tokens[compared:])\n\n    acceptance_rate = (accepted / compared) if compared else 0.0\n    return {\n        "accepted_tokens": accepted,\n        "compared_tokens": compared,\n        "acceptance_rate": round(acceptance_rate, 4),\n        "output_tokens": out_tokens,\n    }\n\n\ndef run_speculative_decode(payload: dict) -> dict:\n    draft_tokens = payload.get("draft_tokens", [])\n    target_tokens = payload.get("target_tokens", [])\n\n    if isinstance(draft_tokens, list) and isinstance(target_tokens, list) and (draft_tokens or target_tokens):\n        result = run_speculative_loop(\n            draft_tokens=[str(t) for t in draft_tokens],\n            target_tokens=[str(t) for t in target_tokens],\n        )\n        result["source"] = "provided_tokens"\n        return result\n\n    prompt = str(payload.get("prompt", "") or "").strip()\n    if not prompt:\n        raise ValueError("missing_prompt_or_tokens")\n\n    draft_model = str(payload.get("draft_model") or os.environ.get("SPEC_DRAFT_MODEL", "local-mlx-fast"))\n    target_model = str(payload.get("target_model") or os.environ.get("SPEC_TARGET_MODEL", "local-mlx"))\n    draft_url = str(\n        payload.get("draft_url") or os.environ.get("SPEC_DRAFT_URL", "http://localhost:4000/v1/completions")\n    )\n    target_url = str(\n        payload.get("target_url") or os.environ.get("SPEC_TARGET_URL", "http://localhost:4000/v1/completions")\n    )\n    max_tokens = int(payload.get("max_tokens", 128) or 128)\n    timeout = float(payload.get("timeout", 20.0) or 20.0)\n    stream_loop = bool(payload.get("stream_loop", True))\n\n    if stream_loop:\n        result = run_streaming_acceptance_loop(\n            prompt=prompt,\n            draft_model=draft_model,\n            target_model=target_model,\n            draft_url=draft_url,\n            target_url=target_url,\n            max_tokens=max_tokens,\n            timeout=timeout,\n        )\n        result.update(\n            {\n                "source": "model_calls",\n                "draft_model": draft_model,\n                "target_model": target_model,\n            }\n        )\n        return result\n\n    draft_tokens_out: list[str] = []\n    target_tokens_out: list[str] = []\n    draft_ms = 0.0\n    target_ms = 0.0\n    draft_error = ""\n\n    try:\n        draft_tokens_out, draft_ms = request_model_tokens(\n            api_url=draft_url,\n            model=draft_model,\n            prompt=prompt,\n            max_tokens=max_tokens,\n            timeout=timeout,\n        )\n    except Exception as e:\n        draft_error = str(e)\n\n    target_tokens_out, target_ms = request_model_tokens(\n        api_url=target_url,\n        model=target_model,\n        prompt=prompt,\n        max_tokens=max_tokens,\n        timeout=timeout,\n    )\n\n    result = run_speculative_loop(draft_tokens=draft_tokens_out, target_tokens=target_tokens_out)\n    result.update(\n        {\n            "source": "model_calls",\n            "draft_model": draft_model,\n            "target_model": target_model,\n            "draft_token_count": len(draft_tokens_out),\n            "target_token_count": len(target_tokens_out),\n            "draft_call_ms": round(draft_ms, 2),\n            "target_call_ms": round(target_ms, 2),\n        }\n    )\n    if draft_error:\n        result["draft_error"] = draft_error\n    return result\n\n\nclass Handler(BaseHTTPRequestHandler):\n    def _reply(self, payload: dict, status: int = 200) -> None:\n        self.send_response(status)\n        self.send_header("Content-Type", "application/json")\n        self.end_headers()\n        self.wfile.write(json.dumps(payload).encode("utf-8"))\n\n    def do_GET(self):\n        if self.path == "/health":\n            self._reply({"ok": True, "service": "spec-router"})\n            return\n        self._reply({"error": "not found"}, status=404)\n\n    def do_POST(self):\n        if self.path != "/spec/decode":\n            self._reply({"error": "not found"}, status=404)\n            return\n\n        try:\n            content_length = int(self.headers.get("Content-Length", "0"))\n        except ValueError:\n            content_length = 0\n        body = self.rfile.read(max(0, content_length))\n\n        try:\n            payload = json.loads(body.decode("utf-8") if body else "{}")\n        except Exception:\n            self._reply({"error": "invalid_json"}, status=400)\n            return\n\n        try:\n            result = run_speculative_decode(payload)\n        except ValueError as e:\n            self._reply({"error": str(e)}, status=400)\n            return\n        except urllib.error.URLError as e:\n            self._reply({"error": "model_backend_unreachable", "detail": str(e)}, status=502)\n            return\n        except Exception as e:\n            self._reply({"error": "decode_failed", "detail": str(e)}, status=500)\n            return\n        self._reply({"ok": True, "service": "spec-router", "result": result})\n\n\nif __name__ == "__main__":\n    server = HTTPServer(("0.0.0.0", 8092), Handler)\n    print("Spec router listening on :8092")\n    server.serve_forever()\n'

EMBED_QUEUE_SERVER = 'from __future__ import annotations\n\nimport json\nimport os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\n\n\nDB_PATH = Path(\'.ai-dev/embedding_jobs.db\')\nEVENT_LOG_PATH = Path(\'.ai-dev/events/embed-queue.jsonl\')\n\n\ndef emit_event(event_type: str, **fields: object) -> None:\n    EVENT_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)\n    rec = {\n        \'ts\': time.time(),\n        \'service\': \'embed-queue\',\n        \'event\': event_type,\n        **fields,\n    }\n    with EVENT_LOG_PATH.open(\'a\', encoding=\'utf-8\') as f:\n        f.write(json.dumps(rec) + \'\\n\')\n\n\ndef parse_dead_letter_threshold() -> int:\n    raw = os.environ.get(\'EMBED_QUEUE_ALERT_DEAD_LETTER\', \'5\')\n    try:\n        return max(0, int(raw))\n    except ValueError:\n        return 5\n\n\ndef compute_alerts(stats: dict, dead_letter_threshold: int) -> list[dict]:\n    alerts: list[dict] = []\n    dead_letter = int(stats.get(\'dead_letter\', 0) or 0)\n    if dead_letter >= max(0, int(dead_letter_threshold)):\n        alerts.append(\n            {\n                \'name\': \'dead_letter_threshold_exceeded\',\n                \'severity\': \'warning\',\n                \'value\': dead_letter,\n                \'threshold\': int(dead_letter_threshold),\n                \'message\': f\'dead_letter jobs ({dead_letter}) >= threshold ({dead_letter_threshold})\',\n            }\n        )\n    return alerts\n\n\ndef _db_connect() -> sqlite3.Connection:\n    DB_PATH.parent.mkdir(parents=True, exist_ok=True)\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\ndef _init_db() -> None:\n    with _db_connect() as conn:\n        conn.execute(\n            \'\'\'\n            CREATE TABLE IF NOT EXISTS embedding_jobs (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                kind TEXT NOT NULL,\n                payload_json TEXT NOT NULL,\n                status TEXT NOT NULL,\n                attempts INTEGER NOT NULL DEFAULT 0,\n                max_attempts INTEGER NOT NULL DEFAULT 3,\n                next_attempt_at REAL NOT NULL DEFAULT 0,\n                last_error TEXT,\n                created_at REAL NOT NULL,\n                updated_at REAL NOT NULL\n            )\n            \'\'\'\n        )\n        conn.commit()\n\n\ndef enqueue_job(kind: str, payload: dict, max_attempts: int = 3) -> dict:\n    now = time.time()\n    with _db_connect() as conn:\n        cur = conn.execute(\n            \'\'\'\n            INSERT INTO embedding_jobs (\n                kind, payload_json, status, attempts, max_attempts, next_attempt_at, created_at, updated_at\n            ) VALUES (?, ?, \'queued\', 0, ?, 0, ?, ?)\n            \'\'\',\n            (kind, json.dumps(payload), max(1, int(max_attempts)), now, now),\n        )\n        conn.commit()\n        out = {\'job_id\': int(cur.lastrowid), \'status\': \'queued\'}\n        emit_event(\'job_enqueued\', job_id=out[\'job_id\'], kind=kind, max_attempts=max_attempts)\n        return out\n\n\ndef claim_next_job() -> dict | None:\n    now = time.time()\n    with _db_connect() as conn:\n        conn.execute(\'BEGIN IMMEDIATE\')\n        row = conn.execute(\n            \'\'\'\n            SELECT * FROM embedding_jobs\n            WHERE status IN (\'queued\', \'retry\')\n              AND next_attempt_at <= ?\n            ORDER BY id ASC\n            LIMIT 1\n            \'\'\',\n            (now,),\n        ).fetchone()\n\n        if row is None:\n            conn.commit()\n            return None\n\n        next_attempts = int(row[\'attempts\']) + 1\n        conn.execute(\n            \'\'\'\n            UPDATE embedding_jobs\n            SET status=\'in_progress\', attempts=?, updated_at=?\n            WHERE id=?\n            \'\'\',\n            (next_attempts, now, int(row[\'id\'])),\n        )\n        conn.commit()\n\n        out = {\n            \'id\': int(row[\'id\']),\n            \'kind\': row[\'kind\'],\n            \'payload\': json.loads(row[\'payload_json\']),\n            \'attempts\': next_attempts,\n            \'max_attempts\': int(row[\'max_attempts\']),\n        }\n        emit_event(\'job_claimed\', job_id=out[\'id\'], attempts=next_attempts, kind=out[\'kind\'])\n        return out\n\n\ndef complete_job(job_id: int) -> None:\n    now = time.time()\n    with _db_connect() as conn:\n        conn.execute(\n            "UPDATE embedding_jobs SET status=\'done\', updated_at=? WHERE id=?",\n            (now, int(job_id)),\n        )\n        conn.commit()\n    emit_event(\'job_completed\', job_id=int(job_id))\n\n\ndef fail_job(job_id: int, error: str) -> dict:\n    now = time.time()\n    with _db_connect() as conn:\n        row = conn.execute(\n            \'SELECT attempts, max_attempts FROM embedding_jobs WHERE id=?\',\n            (int(job_id),),\n        ).fetchone()\n        if row is None:\n            return {\'error\': \'job_not_found\'}\n\n        attempts = int(row[\'attempts\'])\n        max_attempts = int(row[\'max_attempts\'])\n        if attempts >= max_attempts:\n            status = \'dead_letter\'\n            next_attempt_at = 0\n        else:\n            status = \'retry\'\n            next_attempt_at = now + min(60.0, float(2 ** attempts))\n\n        conn.execute(\n            \'\'\'\n            UPDATE embedding_jobs\n            SET status=?, next_attempt_at=?, last_error=?, updated_at=?\n            WHERE id=?\n            \'\'\',\n            (status, next_attempt_at, str(error)[:2000], now, int(job_id)),\n        )\n        conn.commit()\n        out = {\'ok\': True, \'status\': status, \'next_attempt_at\': next_attempt_at}\n        emit_event(\n            \'job_failed\',\n            job_id=int(job_id),\n            status=status,\n            attempts=attempts,\n            max_attempts=max_attempts,\n            error=str(error)[:300],\n        )\n        return out\n\n\ndef get_stats() -> dict:\n    with _db_connect() as conn:\n        counts = {\n            row[\'status\']: int(row[\'count\'])\n            for row in conn.execute(\n                \'SELECT status, COUNT(*) AS count FROM embedding_jobs GROUP BY status\'\n            ).fetchall()\n        }\n    return {\n        \'queued\': counts.get(\'queued\', 0),\n        \'retry\': counts.get(\'retry\', 0),\n        \'in_progress\': counts.get(\'in_progress\', 0),\n        \'done\': counts.get(\'done\', 0),\n        \'dead_letter\': counts.get(\'dead_letter\', 0),\n    }\n\n\nclass Handler(BaseHTTPRequestHandler):\n    def _reply(self, payload: dict, status: int = 200) -> None:\n        self.send_response(status)\n        self.send_header(\'Content-Type\', \'application/json\')\n        self.end_headers()\n        self.wfile.write(json.dumps(payload).encode(\'utf-8\'))\n\n    def _read_json(self) -> dict:\n        try:\n            n = int(self.headers.get(\'Content-Length\', \'0\'))\n        except ValueError:\n            n = 0\n        body = self.rfile.read(max(0, n))\n        if not body:\n            return {}\n        try:\n            parsed = json.loads(body.decode(\'utf-8\'))\n            return parsed if isinstance(parsed, dict) else {}\n        except Exception:\n            return {}\n\n    def do_GET(self):\n        if self.path == \'/health\':\n            self._reply({\'ok\': True, \'service\': \'embed-queue\', \'db_path\': str(DB_PATH)})\n            return\n        if self.path == \'/stats\':\n            stats = get_stats()\n            threshold = parse_dead_letter_threshold()\n            alerts = compute_alerts(stats, dead_letter_threshold=threshold)\n            if alerts:\n                emit_event(\'alerts_emitted\', alerts=alerts)\n            self._reply(\n                {\n                    \'ok\': True,\n                    \'service\': \'embed-queue\',\n                    \'stats\': stats,\n                    \'alerts\': alerts,\n                    \'alert_thresholds\': {\'dead_letter\': threshold},\n                }\n            )\n            return\n        self._reply({\'error\': \'not found\'}, status=404)\n\n    def do_POST(self):\n        if self.path == \'/jobs/enqueue\':\n            payload = self._read_json()\n            kind = str(payload.get(\'kind\', \'file_change\') or \'file_change\')\n            job_payload = payload.get(\'payload\', {}) if isinstance(payload.get(\'payload\', {}), dict) else {}\n            max_attempts = int(payload.get(\'max_attempts\', 3) or 3)\n            out = enqueue_job(kind=kind, payload=job_payload, max_attempts=max_attempts)\n            self._reply({\'ok\': True, \'service\': \'embed-queue\', **out})\n            return\n\n        if self.path == \'/jobs/claim\':\n            job = claim_next_job()\n            self._reply({\'ok\': True, \'service\': \'embed-queue\', \'job\': job})\n            return\n\n        if self.path == \'/jobs/complete\':\n            payload = self._read_json()\n            job_id = int(payload.get(\'job_id\', 0) or 0)\n            if job_id <= 0:\n                self._reply({\'error\': \'missing_job_id\'}, status=400)\n                return\n            complete_job(job_id)\n            self._reply({\'ok\': True, \'service\': \'embed-queue\', \'job_id\': job_id, \'status\': \'done\'})\n            return\n\n        if self.path == \'/jobs/fail\':\n            payload = self._read_json()\n            job_id = int(payload.get(\'job_id\', 0) or 0)\n            if job_id <= 0:\n                self._reply({\'error\': \'missing_job_id\'}, status=400)\n                return\n            error = str(payload.get(\'error\', \'unknown_error\'))\n            out = fail_job(job_id=job_id, error=error)\n            if out.get(\'error\'):\n                self._reply(out, status=404)\n                return\n            self._reply({\'ok\': True, \'service\': \'embed-queue\', \'job_id\': job_id, **out})\n            return\n\n        self._reply({\'error\': \'not found\'}, status=404)\n\n\nif __name__ == \'__main__\':\n    _init_db()\n    server = HTTPServer((\'0.0.0.0\', 8093), Handler)\n    print(\'Embedding queue listening on :8093\')\n    server.serve_forever()\n'

EMBED_WORKER = "from __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport shutil\nimport time\nimport urllib.error\nimport urllib.request\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\nEMBEDDING_SCHEMA_VERSION = 2\nEVENT_LOG_PATH = Path('.ai-dev/events/embed-worker.jsonl')\n\n\ndef emit_event(event_type: str, **fields: object) -> None:\n    EVENT_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)\n    rec = {\n        'ts': time.time(),\n        'service': 'embed-worker',\n        'event': event_type,\n        **fields,\n    }\n    with EVENT_LOG_PATH.open('a', encoding='utf-8') as f:\n        f.write(json.dumps(rec) + '\\n')\n\n\ndef http_json(method: str, url: str, payload: dict | None = None, timeout: float = 10.0) -> dict:\n    data = json.dumps(payload or {}).encode('utf-8') if payload is not None else None\n    req = urllib.request.Request(\n        url,\n        data=data,\n        headers={'Content-Type': 'application/json'},\n        method=method,\n    )\n    with urllib.request.urlopen(req, timeout=timeout) as resp:\n        raw = resp.read().decode('utf-8')\n    return json.loads(raw) if raw else {}\n\n\ndef fake_embed(text: str, dims: int = 16) -> list[float]:\n    digest = hashlib.sha256((text or '').encode('utf-8')).digest()\n    vals = [((digest[i % len(digest)] / 255.0) * 2.0 - 1.0) for i in range(dims)]\n    norm = math.sqrt(sum(v * v for v in vals)) or 1.0\n    return [round(v / norm, 6) for v in vals]\n\n\ndef _coerce_vector(vec: object) -> list[float]:\n    if not isinstance(vec, list):\n        return []\n    out: list[float] = []\n    for x in vec:\n        try:\n            out.append(float(x))\n        except (TypeError, ValueError):\n            return []\n    return out\n\n\ndef _extract_source_text(payload: dict) -> str:\n    source_text = str(payload.get('text', '') or '')\n    if not source_text:\n        source_text = str(payload.get('path', '') or '')\n    if not source_text:\n        source_text = json.dumps(payload, sort_keys=True)\n    return source_text\n\n\ndef _embed_via_http(text: str, embed_url: str, embed_model: str, timeout: float) -> list[float]:\n    body = {\n        'model': embed_model,\n        'input': text,\n    }\n    resp = http_json('POST', embed_url, payload=body, timeout=timeout)\n    data = resp.get('data', []) if isinstance(resp, dict) else []\n    if not isinstance(data, list) or not data:\n        raise ValueError('missing_embedding_data')\n    first = data[0] if isinstance(data[0], dict) else {}\n    vec = _coerce_vector(first.get('embedding'))\n    if not vec:\n        raise ValueError('invalid_embedding_vector')\n    return vec\n\n\ndef _load_schema(schema_path: Path) -> dict:\n    if not schema_path.exists():\n        return {}\n    try:\n        parsed = json.loads(schema_path.read_text(encoding='utf-8'))\n        return parsed if isinstance(parsed, dict) else {}\n    except Exception:\n        return {}\n\n\ndef _save_schema(schema_path: Path, schema: dict) -> None:\n    schema_path.parent.mkdir(parents=True, exist_ok=True)\n    schema_path.write_text(json.dumps(schema, indent=2) + '\\n', encoding='utf-8')\n\n\ndef _append_migration_event(migration_log_path: Path, event: dict) -> None:\n    migration_log_path.parent.mkdir(parents=True, exist_ok=True)\n    with migration_log_path.open('a', encoding='utf-8') as f:\n        f.write(json.dumps(event) + '\\n')\n\n\ndef _rotate_output_for_migration(output_path: Path, old_schema: dict, migration_log_path: Path) -> None:\n    if not output_path.exists() or not output_path.is_file():\n        return\n    ts = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')\n    rotated = output_path.with_suffix(output_path.suffix + f'.migrated-{ts}.bak')\n    shutil.move(str(output_path), str(rotated))\n    _append_migration_event(\n        migration_log_path,\n        {\n            'event': 'embedding_schema_migration',\n            'migrated_at': datetime.now(timezone.utc).isoformat(),\n            'old_schema': old_schema,\n            'rotated_output_path': str(rotated),\n        },\n    )\n\n\ndef ensure_embedding_schema(\n    schema_path: Path,\n    output_path: Path,\n    migration_log_path: Path,\n    *,\n    embedding_model: str,\n    vector_dim: int,\n    backend: str,\n    allow_migrate: bool,\n) -> dict:\n    now_iso = datetime.now(timezone.utc).isoformat()\n    expected = {\n        'schema_version': EMBEDDING_SCHEMA_VERSION,\n        'embedding_model': embedding_model,\n        'vector_dim': int(vector_dim),\n        'backend': backend,\n    }\n    current = _load_schema(schema_path)\n    if not current:\n        out = {**expected, 'created_at': now_iso, 'updated_at': now_iso}\n        _save_schema(schema_path, out)\n        return out\n\n    compatible = (\n        int(current.get('schema_version', 0) or 0) == expected['schema_version']\n        and str(current.get('embedding_model', '')) == expected['embedding_model']\n        and int(current.get('vector_dim', 0) or 0) == expected['vector_dim']\n        and str(current.get('backend', '')) == expected['backend']\n    )\n    if compatible:\n        current['updated_at'] = now_iso\n        _save_schema(schema_path, current)\n        return current\n\n    if not allow_migrate:\n        raise RuntimeError(\n            'embedding_schema_mismatch: pass --allow-schema-migrate to rotate old embeddings and continue'\n        )\n\n    _rotate_output_for_migration(output_path=output_path, old_schema=current, migration_log_path=migration_log_path)\n    out = {**expected, 'created_at': now_iso, 'updated_at': now_iso}\n    _save_schema(schema_path, out)\n    _append_migration_event(\n        migration_log_path,\n        {\n            'event': 'embedding_schema_initialized',\n            'initialized_at': now_iso,\n            'schema': out,\n        },\n    )\n    return out\n\n\ndef qdrant_upsert(\n    *,\n    qdrant_url: str,\n    collection: str,\n    point_id: int,\n    vector: list[float],\n    payload: dict,\n    timeout: float,\n) -> dict:\n    base = qdrant_url.rstrip('/')\n    coll_url = f'{base}/collections/{collection}'\n    try:\n        http_json('GET', coll_url, timeout=timeout)\n    except Exception:\n        http_json(\n            'PUT',\n            coll_url,\n            payload={'vectors': {'size': len(vector), 'distance': 'Cosine'}},\n            timeout=timeout,\n        )\n\n    return http_json(\n        'PUT',\n        f'{coll_url}/points?wait=true',\n        payload={\n            'points': [\n                {\n                    'id': int(point_id),\n                    'vector': vector,\n                    'payload': payload,\n                }\n            ]\n        },\n        timeout=timeout,\n    )\n\n\ndef process_job(\n    job: dict,\n    output_path: Path,\n    schema_path: Path,\n    migration_log_path: Path,\n    *,\n    embed_url: str,\n    embed_model: str,\n    timeout: float,\n    qdrant_url: str,\n    qdrant_collection: str,\n    qdrant_enabled: bool,\n    allow_schema_migrate: bool,\n    force_fake_embed: bool,\n) -> None:\n    emit_event('job_processing_started', job_id=int(job.get('id', 0) or 0), kind=str(job.get('kind', 'unknown')))\n    payload = job.get('payload', {}) if isinstance(job.get('payload', {}), dict) else {}\n    source_text = _extract_source_text(payload)\n\n    vector_backend = 'local_http'\n    if force_fake_embed:\n        vector = fake_embed(source_text)\n        vector_backend = 'deterministic_fallback'\n    else:\n        try:\n            vector = _embed_via_http(source_text, embed_url=embed_url, embed_model=embed_model, timeout=timeout)\n        except Exception:\n            vector = fake_embed(source_text)\n            vector_backend = 'deterministic_fallback'\n\n    schema = ensure_embedding_schema(\n        schema_path=schema_path,\n        output_path=output_path,\n        migration_log_path=migration_log_path,\n        embedding_model=embed_model,\n        vector_dim=len(vector),\n        backend=vector_backend,\n        allow_migrate=allow_schema_migrate,\n    )\n\n    qdrant_status = {'enabled': qdrant_enabled, 'upserted': False}\n    if qdrant_enabled:\n        try:\n            qdrant_upsert(\n                qdrant_url=qdrant_url,\n                collection=qdrant_collection,\n                point_id=int(job.get('id', 0) or 0),\n                vector=vector,\n                payload={\n                    'kind': str(job.get('kind', 'unknown')),\n                    'metadata': payload,\n                    'schema_version': EMBEDDING_SCHEMA_VERSION,\n                    'embedding_model': embed_model,\n                    'vector_backend': vector_backend,\n                },\n                timeout=timeout,\n            )\n            qdrant_status = {'enabled': True, 'upserted': True}\n            emit_event('qdrant_upsert_succeeded', job_id=int(job.get('id', 0) or 0), collection=qdrant_collection)\n        except Exception as e:\n            qdrant_status = {'enabled': True, 'upserted': False, 'error': str(e)[:500]}\n            emit_event('qdrant_upsert_failed', job_id=int(job.get('id', 0) or 0), error=str(e)[:300])\n\n    rec = {\n        'embedded_at': datetime.now(timezone.utc).isoformat(),\n        'schema_version': EMBEDDING_SCHEMA_VERSION,\n        'job_id': int(job.get('id', 0) or 0),\n        'kind': str(job.get('kind', 'unknown')),\n        'embedding_model': embed_model,\n        'vector_backend': vector_backend,\n        'vector_dim': len(vector),\n        'schema': {\n            'embedding_model': schema.get('embedding_model', ''),\n            'vector_dim': int(schema.get('vector_dim', 0) or 0),\n            'backend': schema.get('backend', ''),\n        },\n        'qdrant': qdrant_status,\n        'metadata': payload,\n        'vector': vector,\n    }\n\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    with output_path.open('a', encoding='utf-8') as f:\n        f.write(json.dumps(rec) + '\\n')\n    emit_event(\n        'job_processing_completed',\n        job_id=int(job.get('id', 0) or 0),\n        vector_backend=vector_backend,\n        vector_dim=len(vector),\n        qdrant_upserted=bool(qdrant_status.get('upserted', False)),\n    )\n\n\ndef run_once(queue_url: str, output_path: Path, timeout: float) -> bool:\n    claim = http_json('POST', queue_url.rstrip('/') + '/jobs/claim', payload={}, timeout=timeout)\n    job = claim.get('job') if isinstance(claim, dict) else None\n    if not isinstance(job, dict):\n        return False\n\n    job_id = int(job.get('id', 0) or 0)\n    if job_id <= 0:\n        return False\n\n    try:\n        process_job(\n            job=job,\n            output_path=output_path,\n            schema_path=Path(os.environ.get('EMBED_SCHEMA_PATH', '.ai-dev/embedding_schema.json')),\n            migration_log_path=Path(os.environ.get('EMBED_MIGRATION_LOG_PATH', '.ai-dev/embedding_migrations.jsonl')),\n            embed_url=os.environ.get('EMBED_URL', 'http://localhost:4000/v1/embeddings'),\n            embed_model=os.environ.get('EMBED_MODEL', 'local-embed'),\n            timeout=timeout,\n            qdrant_url=os.environ.get('QDRANT_URL', 'http://localhost:6333'),\n            qdrant_collection=os.environ.get('QDRANT_COLLECTION', 'ai_dev_embeddings'),\n            qdrant_enabled=os.environ.get('QDRANT_ENABLED', '1') not in ('0', 'false', 'False'),\n            allow_schema_migrate=os.environ.get('ALLOW_SCHEMA_MIGRATE', '0') in ('1', 'true', 'True'),\n            force_fake_embed=os.environ.get('FORCE_FAKE_EMBED', '0') in ('1', 'true', 'True'),\n        )\n    except Exception as e:\n        emit_event('job_processing_failed', job_id=job_id, error=str(e)[:300])\n        http_json(\n            'POST',\n            queue_url.rstrip('/') + '/jobs/fail',\n            payload={'job_id': job_id, 'error': str(e)},\n            timeout=timeout,\n        )\n        return True\n\n    http_json(\n        'POST',\n        queue_url.rstrip('/') + '/jobs/complete',\n        payload={'job_id': job_id},\n        timeout=timeout,\n    )\n    emit_event('job_marked_done', job_id=job_id)\n    return True\n\n\ndef main() -> int:\n    p = argparse.ArgumentParser(description='Background embedding worker')\n    p.add_argument('--queue-url', default='http://localhost:8093')\n    p.add_argument('--output-path', default='.ai-dev/embeddings.jsonl')\n    p.add_argument('--poll-interval', type=float, default=2.0)\n    p.add_argument('--timeout', type=float, default=10.0)\n    p.add_argument('--embed-url', default='http://localhost:4000/v1/embeddings')\n    p.add_argument('--embed-model', default='local-embed')\n    p.add_argument('--schema-path', default='.ai-dev/embedding_schema.json')\n    p.add_argument('--migration-log-path', default='.ai-dev/embedding_migrations.jsonl')\n    p.add_argument('--qdrant-url', default='http://localhost:6333')\n    p.add_argument('--qdrant-collection', default='ai_dev_embeddings')\n    p.add_argument('--disable-qdrant', action='store_true')\n    p.add_argument('--allow-schema-migrate', action='store_true')\n    p.add_argument('--force-fake-embed', action='store_true')\n    p.add_argument('--once', action='store_true', help='Process at most one available job and exit')\n    args = p.parse_args()\n\n    os.environ['EMBED_URL'] = str(args.embed_url)\n    os.environ['EMBED_MODEL'] = str(args.embed_model)\n    os.environ['EMBED_SCHEMA_PATH'] = str(args.schema_path)\n    os.environ['EMBED_MIGRATION_LOG_PATH'] = str(args.migration_log_path)\n    os.environ['QDRANT_URL'] = str(args.qdrant_url)\n    os.environ['QDRANT_COLLECTION'] = str(args.qdrant_collection)\n    os.environ['QDRANT_ENABLED'] = '0' if args.disable_qdrant else '1'\n    os.environ['ALLOW_SCHEMA_MIGRATE'] = '1' if args.allow_schema_migrate else '0'\n    os.environ['FORCE_FAKE_EMBED'] = '1' if args.force_fake_embed else '0'\n\n    output_path = Path(args.output_path)\n\n    if args.once:\n        try:\n            run_once(queue_url=args.queue_url, output_path=output_path, timeout=args.timeout)\n            return 0\n        except urllib.error.URLError as e:\n            print(f'worker failed to reach queue: {e}')\n            return 2\n\n    print(f'Embedding worker polling {args.queue_url} every {args.poll_interval}s')\n    while True:\n        try:\n            processed = run_once(queue_url=args.queue_url, output_path=output_path, timeout=args.timeout)\n        except urllib.error.URLError as e:\n            print(f'worker queue error: {e}')\n            processed = False\n\n        if not processed:\n            time.sleep(max(0.25, args.poll_interval))\n\n\nif __name__ == '__main__':\n    raise SystemExit(main())\n"

AGENT_SERVER = 'import json\nimport subprocess\nimport uuid\nimport time\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Optional\nfrom urllib.parse import parse_qs, urlparse\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\n\nfrom agent import cache_kv\nfrom agent import observability\nfrom agent import retrieval\nfrom agent import runtime_context\nfrom agent import schemas\nfrom agent import task_runner\nfrom agent import tooling\n\n\nROOT = Path(__file__).resolve().parents[1]\nINDEX_PATH = tooling.INDEX_PATH\nRUNS_DIR = ROOT / ".ai-dev" / "runs"\nCACHE_PATH = cache_kv.CACHE_PATH\nMETRICS_PATH = ROOT / ".ai-dev" / "metrics.json"\nKV_CACHE_PATH = cache_kv.KV_CACHE_PATH\nEVENT_LOG_PATH = ROOT / ".ai-dev" / "events" / "agent.jsonl"\nDEFAULT_CACHE_TTL_SECONDS = 600\nDEFAULT_KV_MODEL_BUDGET_TOKENS = cache_kv.DEFAULT_KV_MODEL_BUDGET_TOKENS\nDEFAULT_KV_ENTRY_MAX_TOKENS = cache_kv.DEFAULT_KV_ENTRY_MAX_TOKENS\nALLOWED_TOOLS = schemas.ALLOWED_TOOLS\n\nTOOL_SCHEMAS = schemas.TOOL_SCHEMAS\n\nPATCH_DENY_PREFIXES = tooling.PATCH_DENY_PREFIXES\n\n\ndef emit_event(event_type: str, **fields: object) -> None:\n    observability.emit_event(event_type, event_log_path=EVENT_LOG_PATH, **fields)\n\n\ndef parse_alert_thresholds() -> dict:\n    return observability.parse_alert_thresholds()\n\n\ndef compute_alerts(metrics: dict, thresholds: dict) -> list[dict]:\n    return observability.compute_alerts(metrics, thresholds=thresholds)\n\n\ndef utc_now_iso() -> str:\n    return observability.utc_now_iso()\n\n\ndef load_json_file(path: Path, default):\n    return cache_kv.load_json_file(path, default)\n\n\ndef save_json_file(path: Path, payload: dict) -> None:\n    cache_kv.save_json_file(path, payload)\n\n\ndef get_git_branch() -> str:\n    return runtime_context.get_git_branch(root=ROOT)\n\n\ndef get_index_signature() -> str:\n    return runtime_context.get_index_signature(index_path=INDEX_PATH)\n\n\ndef compute_cache_namespace() -> str:\n    return runtime_context.compute_cache_namespace(root=ROOT, index_path=INDEX_PATH)\n\n\ndef normalize_task_payload(payload: dict) -> dict:\n    return runtime_context.normalize_task_payload(payload)\n\n\ndef compute_cache_key(payload: dict) -> str:\n    return runtime_context.compute_cache_key(payload)\n\n\ndef load_cache() -> dict:\n    return cache_kv.load_cache()\n\n\ndef save_cache(cache_obj: dict) -> None:\n    cache_kv.save_cache(cache_obj)\n\n\ndef get_cache_entry(cache_obj: dict, key: str, namespace: str) -> Optional[dict]:\n    return cache_kv.get_cache_entry(cache_obj, key=key, namespace=namespace)\n\n\ndef set_cache_entry(cache_obj: dict, key: str, namespace: str, result: dict, ttl_seconds: int) -> None:\n    cache_kv.set_cache_entry(cache_obj, key=key, namespace=namespace, result=result, ttl_seconds=ttl_seconds)\n\n\ndef load_metrics() -> dict:\n    return observability.load_metrics(metrics_path=METRICS_PATH)\n\n\ndef record_cache_metrics(hit: bool, compute_ms: float, namespace: str, key: str) -> None:\n    observability.record_cache_metrics(hit, compute_ms=compute_ms, namespace=namespace, key=key, metrics_path=METRICS_PATH)\n\n\ndef record_tool_metrics(tool: str, ok: bool, duration_ms: float, error: str = "") -> None:\n    observability.record_tool_metrics(\n        tool,\n        ok=ok,\n        duration_ms=duration_ms,\n        error=error,\n        metrics_path=METRICS_PATH,\n    )\n\n\ndef estimate_tokens(text: str) -> int:\n    return cache_kv.estimate_tokens(text)\n\n\ndef normalize_prefix_text(payload: dict) -> str:\n    return cache_kv.normalize_prefix_text(payload)\n\n\ndef hash_prefix(prefix: str) -> str:\n    return cache_kv.hash_prefix(prefix)\n\n\ndef load_kv_cache() -> dict:\n    return cache_kv.load_kv_cache()\n\n\ndef save_kv_cache(obj: dict) -> None:\n    cache_kv.save_kv_cache(obj)\n\n\ndef _ensure_model_store(kv_obj: dict, model: str, budget_tokens: int) -> dict:\n    return cache_kv._ensure_model_store(kv_obj, model=model, budget_tokens=budget_tokens)\n\n\ndef _enforce_model_budget(store: dict, keep_key: str) -> list[str]:\n    return cache_kv._enforce_model_budget(store, keep_key=keep_key)\n\n\ndef get_kv_reuse_status(payload: dict) -> dict:\n    return cache_kv.get_kv_reuse_status(payload)\n\n\ndef tokenize(text: str) -> list[str]:\n    return retrieval.tokenize(text)\n\n\ndef retrieve(index_obj: dict, query: str, top_k: int = 5, path_prefix: Optional[str] = None) -> dict:\n    return retrieval.retrieve(index_obj=index_obj, query=query, top_k=top_k, path_prefix=path_prefix)\n\n\ndef ensure_under_root(path: Path) -> bool:\n    return tooling.ensure_under_root(path)\n\n\ndef normalize_patch_path(path_text: str) -> Optional[str]:\n    return tooling.normalize_patch_path(path_text)\n\n\ndef extract_patch_paths(patch_text: str) -> list[str]:\n    return tooling.extract_patch_paths(patch_text)\n\n\ndef path_allowed_for_patch(rel_path: str) -> bool:\n    return tooling.path_allowed_for_patch(rel_path)\n\n\ndef snapshot_paths(rel_paths: list[str]) -> dict:\n    return tooling.snapshot_paths(rel_paths)\n\n\ndef restore_snapshot(snapshot: dict) -> None:\n    tooling.restore_snapshot(snapshot)\n\n\ndef tool_search_code(args: dict) -> dict:\n    return tooling.tool_search_code(args)\n\n\ndef tool_read_file(args: dict) -> dict:\n    return tooling.tool_read_file(args)\n\n\ndef tool_git_diff(_: dict) -> dict:\n    return tooling.tool_git_diff(_)\n\n\ndef tool_run_tests(args: dict, dry_run: bool) -> dict:\n    return tooling.tool_run_tests(args, dry_run=dry_run)\n\n\ndef tool_write_patch(args: dict, dry_run: bool) -> dict:\n    return tooling.tool_write_patch(args, dry_run=dry_run)\n\n\ndef tool_commit_changes(args: dict, dry_run: bool) -> dict:\n    return tooling.tool_commit_changes(args, dry_run=dry_run)\n\n\ndef execute_tool_call(tool: str, args: dict, dry_run: bool) -> dict:\n    return tooling.execute_tool_call(\n        tool=tool,\n        args=args,\n        dry_run=dry_run,\n        allowed_tools=ALLOWED_TOOLS,\n        retrieve_fn=retrieve,\n    )\n\n\ndef run_agent_task(payload: dict) -> dict:\n    return task_runner.run_agent_task(\n        payload,\n        execute_tool_call_fn=execute_tool_call,\n        record_tool_metrics_fn=record_tool_metrics,\n        emit_event_fn=emit_event,\n        runs_dir=RUNS_DIR,\n        root=ROOT,\n        perf_counter_fn=time.perf_counter,\n    )\n\n\nclass Handler(BaseHTTPRequestHandler):\n    def _reply(self, payload, status=200):\n        self.send_response(status)\n        self.send_header(\'Content-Type\', \'application/json\')\n        self.end_headers()\n        self.wfile.write(json.dumps(payload).encode(\'utf-8\'))\n\n    def do_GET(self):\n        parsed = urlparse(self.path)\n\n        if parsed.path == \'/metrics\':\n            metrics = load_metrics()\n            kv_obj = load_kv_cache()\n            kv_summary = {}\n            for model_name, store in kv_obj.get("models", {}).items():\n                if not isinstance(store, dict):\n                    continue\n                entries = store.get("entries", {}) if isinstance(store.get("entries", {}), dict) else {}\n                kv_summary[model_name] = {\n                    "entries": len(entries),\n                    "used_tokens": int(store.get("used_tokens", 0)),\n                    "budget_tokens": int(store.get("budget_tokens", DEFAULT_KV_MODEL_BUDGET_TOKENS)),\n                }\n            thresholds = parse_alert_thresholds()\n            alerts = compute_alerts(metrics, thresholds=thresholds)\n            if alerts:\n                emit_event(\'alerts_emitted\', alerts=alerts)\n            self._reply(\n                {\n                    \'ok\': True,\n                    \'service\': \'agent\',\n                    \'metrics\': metrics,\n                    \'kv_cache\': {\'models\': kv_summary},\n                    \'alerts\': alerts,\n                    \'alert_thresholds\': thresholds,\n                }\n            )\n            return\n\n        if parsed.path == \'/tools\':\n            self._reply({\'ok\': True, \'service\': \'agent\', \'tools\': TOOL_SCHEMAS})\n            return\n\n        if parsed.path.startswith(\'/runs/\'):\n            run_id = parsed.path.split(\'/runs/\', 1)[1].strip()\n            target = (RUNS_DIR / f"{run_id}.json").resolve()\n            if not target.exists() or not target.is_file() or not ensure_under_root(target):\n                self._reply({\'error\': \'run_not_found\'}, status=404)\n                return\n            payload = json.loads(target.read_text(encoding=\'utf-8\'))\n            self._reply({\'ok\': True, \'service\': \'agent\', \'run\': payload})\n            return\n\n        if parsed.path == \'/retrieve\':\n            if not INDEX_PATH.exists():\n                self._reply({\'error\': \'missing_index\', \'detail\': \'Run `ai-dev index .` first.\'}, status=400)\n                return\n\n            qs = parse_qs(parsed.query)\n            query = (qs.get(\'q\', [\'\'])[0] or \'\').strip()\n            if not query:\n                self._reply({\'error\': \'missing_query\', \'detail\': \'Provide q=<query>\'}, status=400)\n                return\n\n            try:\n                top_k = int((qs.get(\'top_k\', [\'5\'])[0] or \'5\'))\n            except ValueError:\n                top_k = 5\n            top_k = max(1, min(top_k, 20))\n            path_prefix = (qs.get(\'path_prefix\', [\'\'])[0] or \'\').strip() or None\n\n            index_obj = json.loads(INDEX_PATH.read_text(encoding=\'utf-8\'))\n            payload = retrieve(index_obj, query=query, top_k=top_k, path_prefix=path_prefix)\n            self._reply({\'ok\': True, \'service\': \'agent\', \'retrieval\': payload})\n            return\n\n        if parsed.path == \'/health\':\n            self._reply({\'ok\': True, \'service\': \'agent\'})\n            return\n\n        self._reply({\'error\': \'not found\'}, status=404)\n\n    def do_POST(self):\n        parsed = urlparse(self.path)\n        if parsed.path != \'/agent/run\':\n            self._reply({\'error\': \'not found\'}, status=404)\n            return\n\n        try:\n            content_length = int(self.headers.get(\'Content-Length\', \'0\'))\n        except ValueError:\n            content_length = 0\n        body = self.rfile.read(max(0, content_length))\n\n        try:\n            payload = json.loads(body.decode(\'utf-8\') if body else \'{}\')\n        except Exception:\n            self._reply({\'error\': \'invalid_json\'}, status=400)\n            return\n\n        payload = payload if isinstance(payload, dict) else {}\n        cache_cfg = payload.get("cache", {}) if isinstance(payload.get("cache", {}), dict) else {}\n        cache_enabled = bool(cache_cfg.get("enabled", True))\n        cache_refresh = bool(cache_cfg.get("refresh", False))\n        ttl_seconds = int(cache_cfg.get("ttl_seconds", DEFAULT_CACHE_TTL_SECONDS) or DEFAULT_CACHE_TTL_SECONDS)\n        ttl_seconds = max(1, min(ttl_seconds, 86_400))\n\n        namespace = compute_cache_namespace()\n        key = compute_cache_key(payload)\n        cache_hit = False\n        kv_status = get_kv_reuse_status(payload)\n        started = time.perf_counter()\n        result = None\n\n        if cache_enabled and not cache_refresh:\n            cache_obj = load_cache()\n            entry = get_cache_entry(cache_obj, key=key, namespace=namespace)\n            if entry and isinstance(entry.get("result"), dict):\n                result = entry["result"]\n                cache_hit = True\n                save_cache(cache_obj)\n\n        if result is None:\n            result = run_agent_task(payload)\n            if cache_enabled:\n                cache_obj = load_cache()\n                set_cache_entry(cache_obj, key=key, namespace=namespace, result=result, ttl_seconds=ttl_seconds)\n                save_cache(cache_obj)\n\n        compute_ms = (time.perf_counter() - started) * 1000.0\n        record_cache_metrics(hit=cache_hit, compute_ms=compute_ms, namespace=namespace, key=key)\n\n        self._reply(\n            {\n                \'ok\': True,\n                \'service\': \'agent\',\n                \'result\': result,\n                \'cache\': {\n                    \'enabled\': cache_enabled,\n                    \'refresh\': cache_refresh,\n                    \'hit\': cache_hit,\n                    \'ttl_seconds\': ttl_seconds,\n                    \'namespace\': namespace,\n                    \'key\': key,\n                    \'compute_ms\': round(compute_ms, 2),\n                },\n                \'kv_cache\': kv_status,\n            }\n        )\n\n\nif __name__ == \'__main__\':\n    server = HTTPServer((\'0.0.0.0\', 8091), Handler)\n    print(\'Agent service listening on :8091\')\n    server.serve_forever()\n'
